SELECT

FROM UserInvite a WHERE 1 = 1

    AND a.inviterId = #{inviterId}


    AND a.inviteeId = #{inviteeId}


    AND a.inviteType = #{inviteType}


    AND a.inviteCodeUsed = #{inviteCodeUsed}


    AND a.isValid = #{isValid}


    AND a.createTime = #{createTime}


    AND a.updateTime = #{updateTime}

limit 1

SELECT

FROM UserInvite a WHERE 1 = 1

    AND a.inviterId = #{inviterId}


    AND a.inviteeId = #{inviteeId}


    AND a.inviteType LIKE CONCAT('%',#{inviteType}, '%')


    AND a.inviteCodeUsed LIKE CONCAT('%',#{inviteCodeUsed}, '%')


    AND a.isValid = #{isValid}


    AND a.createTime = #{createTime}


    AND a.updateTime = #{updateTime}
